package com.example.application_service.service;import com.example.application_service.entity.*;import com.example.application_service.event.ApplicationEvent;import com.example.application_service.repository.OutboxEventRepository;import org.springframework.stereotype.Service;import tools.jackson.databind.json.JsonMapper;import java.time.Instant;import java.util.UUID;
@Service public class OutboxService{public static final int VERSION=1;private final OutboxEventRepository outbox;private final JsonMapper json;public OutboxService(OutboxEventRepository o,JsonMapper j){outbox=o;json=j;}public void submitted(JobApplication a,String trace){save(a,"APPLICATION_SUBMITTED",null,a.getStatus().name(),trace);}public void statusChanged(JobApplication a,ApplicationStatus old,String trace){save(a,"APPLICATION_STATUS_CHANGED",old.name(),a.getStatus().name(),trace);}private void save(JobApplication a,String type,String oldStatus,String newStatus,String trace){UUID id=UUID.randomUUID();var data=new ApplicationEvent.Data(a.getId(),a.getJobId(),a.getCompanyId(),a.getCandidateId(),a.getCandidateIdentitySnapshot(),a.getJobTitleSnapshot(),oldStatus,newStatus,trace);var event=new ApplicationEvent(id,type,VERSION,Instant.now(),"application-service",data);outbox.save(new OutboxEvent(id,a.getId(),type,VERSION,json.writeValueAsString(event)));}}
